#include "modules/linear_dae_api.h"
#include <algorithm>
#include <cmath>
#include <iostream>
#include <stdexcept>
#include <vector>
namespace {int checks=0;void check(bool yes,const char* text){++checks;if(!yes)throw std::runtime_error(text);}struct Forcing{std::size_t n;double omega=1.3;bool transformed=false;};int force(void* raw,double t,uint32_t order,double* output,char*,uint64_t){const auto& c=*static_cast<Forcing*>(raw);std::fill_n(output,(order+1)*c.n,0.);for(unsigned j=0;j<=order;++j){output[j*c.n+c.n-1]=-std::pow(c.omega,j)*std::sin(c.omega*t+j*std::acos(-1.)/2);if(c.transformed)output[j*c.n+c.n-2]=output[j*c.n+c.n-1];}return 0;}
struct Result{penta_linear_dae_result_v2 report{};std::vector<double>t,y,yp,initial,initialDerivative,basis,projector,reduced;};
Result solve(unsigned index,bool transformed=false,bool initialCheck=false,bool finiteState=true,bool defaultTolerance=false){const auto n=index+(finiteState?1:0);std::vector<double>E(n*n,0),A(n*n,0),initial(n,0);if(finiteState){E[0]=1;A[0]=-2;}for(unsigned row=finiteState?1:0;row<n;++row){A[row*n+row]=1;if(row+1<n)E[row*n+row+1]=1;}Forcing forcing{n,defaultTolerance?1.4:1.3,transformed};const double t0=.2;if(initialCheck&&index>=1){if(finiteState)initial[0]=1;for(unsigned row=finiteState?1:0;row<n;++row){const unsigned derivative=n-1-row;initial[row]=std::pow(forcing.omega,derivative)*std::sin(forcing.omega*t0+derivative*std::acos(-1.)/2);}}else if(finiteState)initial[0]=1;
    if(transformed){check(n==3,"Transform test uses a3x3 index2 system.");const std::vector<double>Q{1,1,1,0,1,1,0,0,1},R{1,1,0,0,1,1,0,0,1};auto multiply=[&](const auto& x,const auto& y){std::vector<double>z(n*n);for(unsigned row=0;row<n;++row)for(unsigned col=0;col<n;++col)for(unsigned j=0;j<n;++j)z[row*n+col]+=x[row*n+j]*y[j*n+col];return z;};E=multiply(multiply(R,E),Q);A=multiply(multiply(R,A),Q);initial={initial[0]-initial[1],initial[1]-initial[2],initial[2]};}
    Result result;const std::size_t samples=104;result.t.resize(samples);result.y.resize(samples*n);result.yp.resize(samples*n);result.initial.resize(n);result.initialDerivative.resize(n);result.basis.resize(n*n);result.projector.resize(n*n);result.reduced.resize(n*n);auto& out=result.report;out.struct_size=sizeof(out);out.capacity=samples;out.times=result.t.data();out.values=result.y.data();out.derivatives=result.yp.data();out.consistent_initial=result.initial.data();out.consistent_derivative=result.initialDerivative.data();out.free_basis=result.basis.data();out.constraint_projector=result.projector.data();out.reduced_matrix=result.reduced.data();out.matrix_capacity=n*n;penta_linear_dae_request_v2 q{};q.struct_size=sizeof(q);q.dimension=n;q.maximum_index=3;q.initialization=initialCheck?0:1;q.mass=E.data();q.linear=A.data();q.initial=initial.data();q.t0=t0;q.t1=1.2;q.sample_step=.01;q.rtol=defaultTolerance?1e-8:1e-9;q.atol=defaultTolerance?1e-10:1e-11;q.rank_tolerance=1e-12;q.condition_limit=1e10;q.residual_tolerance=1e-7;q.max_wall_seconds=30;q.max_steps=q.max_evaluations=100000;q.forcing_context=&forcing;q.forcing=force;const penta_dae_host_v1 host{sizeof(host),PENTA_DAE_ABI_V1,nullptr,nullptr,nullptr};char error[2048]{};const auto api=penta_dae_query_v2(PENTA_DAE_ABI_V2);const auto status=api->linear_solve(&host,&q,&out,error,sizeof(error));if(status)throw std::runtime_error(error);check(out.index==index&&out.differential_dimension==(finiteState?1:0),"Exact manufactured differentiation index and finite dimension recovered.");for(std::size_t sample=0;sample<out.samples;++sample){std::vector<double>truth(n),derivative(n);if(finiteState){truth[0]=std::exp(-2*(out.times[sample]-t0));derivative[0]=-2*truth[0];}for(unsigned row=finiteState?1:0;row<n;++row){const unsigned order=n-1-row;truth[row]=std::pow(forcing.omega,order)*std::sin(forcing.omega*out.times[sample]+order*std::acos(-1.)/2);derivative[row]=std::pow(forcing.omega,order+1)*std::sin(forcing.omega*out.times[sample]+(order+1)*std::acos(-1.)/2);}if(transformed){truth={truth[0]-truth[1],truth[1]-truth[2],truth[2]};derivative={derivative[0]-derivative[1],derivative[1]-derivative[2],derivative[2]};}for(unsigned row=0;row<n;++row)check(std::abs(out.values[sample*n+row]-truth[row])<5e-7&&std::abs(out.derivatives[sample*n+row]-derivative[row])<2e-6,"Full high-index state/derivative agrees with independent manufactured solution.");}return result;}
}
int main(){try{for(unsigned index=1;index<=3;++index){const auto result=solve(index);check(result.report.maximum_scaled_residual<1e-7,"Original scaled descriptor residual validated at retained samples.");}solve(2,true,true);solve(2,false,false,true,true);for(unsigned index=1;index<=3;++index)solve(index,false,false,false);std::cout<<"PASS "<<checks<<" higher-index linear DAE kernel checks\n";}catch(const std::exception&e){std::cerr<<"FAIL after "<<checks<<": "<<e.what()<<'\n';return 1;}}
